const root=process.env.ZODY_CUA_PLUGIN_ROOT ?? process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const {join}=await import('node:path'); const {pathToFileURL}=await import('node:url');
const {setupComputerUseRuntime}=await import(pathToFileURL(join(root,'scripts','computer-use-client.mjs')).href);
await setupComputerUseRuntime({globals:globalThis});
const {readFile}=await import('node:fs/promises');
const f=JSON.parse(await readFile('{{e2eRuntimeRoot}}/cua-r2-capture/manifest.json','utf8'));
const c=agent.computerUse.computer, ref={pid:f.pid,window_id:f.targetWindow};
const initial=await c.get_app_state({app_ref:ref});
if(typeof initial!=='string' || !initial.includes(f.targetMarker) || initial.includes(f.siblingMarker)) throw new Error('R2_CAPTURE_INITIAL_STATE_INVALID');
const elements=initial.split('\n').flatMap(line=>{try{return [JSON.parse(line)]}catch{return []}});
const button=elements.find(e=>(e.title==='R2 Press'||e.title==='E2E_R2_PRESS')&&e.actions?.includes('AXPress'));
if(!button||!Number.isSafeInteger(button.index))throw new Error('R2_CAPTURE_INITIAL_BUTTON_MISSING');
const first=await c.left_click({app_ref:ref,target:{type:'element',index:button.index},return_state:'compact'});
const firstReceipt=first?.content?JSON.parse(first.content[0].text):first;
const firstState=first?.structuredContent;
if(firstReceipt?.action_sent!==true||firstReceipt.dispatch_status!=='sent'||typeof firstState?.state_id!=='string'||firstState?.app?.pid!==f.pid||firstState?.window?.window_id!==f.targetWindow)throw new Error('R2_CAPTURE_FIRST_ACTION_INVALID');
const shot=await c.get_app_state({app_ref:ref,include_screenshot:true});
const blocks=Array.isArray(shot?.content)?shot.content:[];
const images=blocks.filter(b=>b.type==='image'&&b.mimeType==='image/png'&&typeof b.data==='string'&&b.data.length>0);
const tree=blocks.filter(b=>b.type==='text').map(b=>b.text).join('\n');
const state=shot?.structuredContent;
if(images.length!==1||tree.includes(f.siblingMarker)||typeof state?.state_id!=='string'||state.state_id===firstState.state_id||state?.app?.pid!==f.pid||state?.window?.window_id!==f.targetWindow||!Array.isArray(state.elements)||!JSON.stringify(state.elements).includes(f.targetMarker)||JSON.stringify(state.elements).includes(f.siblingMarker))throw new Error('R2_CAPTURE_COMBINED_STATE_INVALID');
const afterButton=state.elements.find(e=>(e.title==='R2 Press'||e.title==='E2E_R2_PRESS')&&e.actions?.includes('AXPress'));
if(!afterButton||!Number.isSafeInteger(afterButton.index))throw new Error('R2_CAPTURE_COMBINED_BUTTON_MISSING');
const second=await c.left_click({app_ref:ref,target:{type:'element',index:afterButton.index},return_state:'none'});
const secondReceipt=second?.content?JSON.parse(second.content[0].text):second;
if(secondReceipt?.action_sent!==true||secondReceipt.dispatch_status!=='sent')throw new Error('R2_CAPTURE_SECOND_ACTION_INVALID');
await nodeRepl.emitImage({base64:images[0].data,mimeType:images[0].mimeType});
nodeRepl.write('R2_CAPTURE_RECEIPT:'+JSON.stringify({pid:f.pid,windowId:f.targetWindow,firstStateId:firstState.state_id,combinedStateId:state.state_id,combinedIndex:afterButton.index,receipts:[firstReceipt,secondReceipt]}));
